// Agente SERPIENTE 🐍 v6 — capa estándar + skill `modoSerpiente` de la librería
//
// Reparto de responsabilidades (REGLAS_AGENTES.md §0):
//   · app.js (framework) ....... no se toca. Es agnóstico a los agentes.
//   · base-npc-skills .......... skill `modoSerpiente`: envuelve a.walk, prohíbe el giro de 180° y pisar
//                                el propio cuerpo, y mantiene a.vars.cuerpo / a.vars.cuerpoSalientes.
//   · este snippet ............. lo que es identidad de LA serpiente: dibujar los segmentos y elegir de
//                                qué material queda el rastro.
//
// POR QUÉ LA REGLA ANTI-MORDISCO VIVE EN LA LIBRERÍA Y NO AQUÍ: el tick estándar llama a a.walk desde
// ~6 sitios distintos (BFS, escape de oscilación, escape por frecuencia, desatasco, desmontar del pino).
// Comprobar la colisión en onTick solo cubriría uno de ellos; envolviendo a.walk la regla se aplica a
// todos. La librería deja una VÁLVULA DE ESCAPE: si ninguna otra dirección es viable permite el paso,
// antes que congelar al agente emitiendo tickets de estancamiento para siempre (se cuenta en
// a.stats.blockedBySelf).
//
// CÓMO SE DIBUJA EL CUERPO SIN TOCAR app.js: cada segmento es OTRO AGENTE, creado con autostart:false y
// dejado en PAUSA. Encaja con el framework tal cual está:
//   · mcAgentsTick (app.js:6428) hace `if(a.state!=='running') continue` → un segmento pausado no decide
//     nada ni consume ticks: quien lo coloca es la cabeza.
//   · mcAgentsSmoothUpdate (app.js:6444) solo salta los 'stopped' → al pausado SÍ le interpola la posición
//     y le vuelve a mallar el cubo cada frame. Basta con asignarle s.x/s.y/s.z y se desliza solo.
//   · el bucle de dibujo (app.js:4798) no mira el estado, solo `vbo && count`.
// Efectos secundarios asumidos: game.agents() lista 11 filas (cabeza + 10 segmentos) y son 11 draw calls.
// Para limpiar del todo: game.kill('all').
//
// OJO: NO usar 'grass' de rastro. El generador pinta TODA la superficie de hierba (app.js:3926-3928), así
// que pintar hierba sobre hierba entra por la rama `prev===id` de a.paint: cuenta como `repainted` y no
// cambia nada — el rastro se quedaba invisible.
//
// Inspección F12: game.agent('serpiente').vars.cuerpo · .stats.blockedBySelf · game.agents() · game.notes()
(async function () {
  if (!game.defineStandardAgent) {
    try {
      var res = await fetch('/api/snippets/base-npc-skills');
      var snip = await res.json();
      if (snip && snip.code) (new Function(snip.code))();
    } catch (e) { console.error('Error cargando base-npc-skills:', e); }
  }

  var LARGO  = 10;      // segmentos de cuerpo visibles DETRÁS de la cabeza
  var CUERPO = 'sand';  // cabeza y segmentos = bloque de arena
  var RASTRO = 'dirt';  // el suelo que ABANDONA la cola se queda de tierra
  var TICK   = 110;
  var SEG    = 'serpiente_seg';

  // Crea (o REEMPLAZA, que defineAgent ya lo hace en silencio) el segmento i, y lo deja pausado.
  // El tickMs TIENE que ser el de la cabeza: mcAgentsSmoothUpdate interpola a 1000/tickMs celdas/s
  // (app.js:6453-6454), así que con el 120 por defecto el cuerpo avanzaría un 9% más lento que la cabeza.
  function nuevoSegmento(i) {
    var s = game.defineAgent({
      id: SEG + i,
      name: 'Serpiente · segmento ' + (i + 1),
      block: CUERPO,
      tickMs: TICK,
      autostart: false,
      passengers: false,
      onTick: function () { }
    });
    if (!s) return null;
    s.start();   // resuelve el material y malla el cubo
    s.pause();   // a partir de aquí solo se mueve cuando la cabeza lo coloca
    return s;
  }

  // a.vars.cuerpo lo mantiene la librería: [0] es la celda pegada a la cabeza, [n-1] la punta de la cola.
  function colocarSegmentos(a) {
    var cuerpo = a.vars.cuerpo || [];
    var segs = a.vars.segs;
    var n = Math.min(LARGO, cuerpo.length);
    for (var i = 0; i < n; i++) {
      if (!segs[i]) segs[i] = nuevoSegmento(i);
      var s = segs[i];
      if (!s) continue;
      var celda = cuerpo[i];
      s.x = celda.x;
      s.z = celda.z;
      var sy = s.surfaceY(celda.x, celda.z);
      if (sy >= 0) s.y = sy;   // apoyado en el suelo aunque el terreno suba
    }
  }

  // La librería va acumulando en cuerpoSalientes las celdas que salen por la punta de la cola; aquí se
  // drenan pintando el rastro. Se vacía siempre, aunque en un tick hayan salido varias.
  function pintarRastro(a) {
    var fuera = a.vars.cuerpoSalientes;
    if (!fuera || !fuera.length) return;
    while (fuera.length) {
      var c = fuera.shift();
      if (a.enqueuePaint) a.enqueuePaint(c.x, c.z, RASTRO);
    }
  }

  var serpiente = game.defineStandardAgent({
    id: 'serpiente',
    name: 'Serpiente',
    block: CUERPO,
    paintBlock: RASTRO,      // que el estándar precargue el material del rastro
    margin: 1,
    passengers: true,
    tickMs: TICK,

    skills: { modoSerpiente: true },
    largoSerpiente: LARGO,   // debe coincidir con los segmentos que dibujamos aquí

    onStart: function (a) {
      // El cuerpo arranca VACÍO (lo inicializa la librería): sembrarlo con LARGO copias del spawn
      // apelotonaría la serpiente entera en la casilla de nacimiento. Los segmentos se van creando
      // según crece el cuerpo, así no hay que esconder ninguno.
      a.vars.segs = [];
    },

    // El tick estándar ya ha movido la cabeza y la librería ya ha actualizado el cuerpo dentro de a.walk
    // (try/finally en base-npc-skills: este onTick se llama SIEMPRE, aunque el tick estándar salga por
    // una de sus ~12 salidas tempranas). Aquí solo queda reflejarlo en pantalla.
    onTick: function (a) {
      pintarRastro(a);
      colocarSegmentos(a);
    }
  });

  console.log('🐍 Serpiente v6 — cuerpo de ' + LARGO + ' segmentos, rastro de ' + RASTRO + '.');
  console.log('   Anti-mordisco y anti-180° = skill `modoSerpiente` de la librería (a.stats.blockedBySelf).');
  console.log('   F12: game.agent("serpiente").vars.cuerpo · game.kill("all") para borrar cabeza y cola.');
})();
